<?php namespace App\Notifications; use App\Models\Document; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Notifications\Notification;
class DocumentActionNotification extends Notification implements ShouldQueue { use Queueable; public function __construct(public Document $document,public string $event,public ?string $message=null){} public function via(object $notifiable):array{return ['database'];} public function toArray(object $notifiable):array{return ['event'=>$this->event,'document_id'=>$this->document->id,'subject'=>$this->document->subject,'deadline'=>$this->document->deadline?->toIso8601String(),'message'=>$this->message];} }
